package com.bank.marketplace.strategy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class RegularFeeStrategy implements FeeStrategy {
    private static final BigDecimal RATE = new BigDecimal("0.010"); // 1%

    @Override
    public BigDecimal calculateFee(BigDecimal amount) {
        return amount.multiply(RATE).setScale(2, RoundingMode.HALF_UP);
    }

    @Override
    public String getName() { return "Regular (1%)"; }
}
