// REST best practices: proper methods, status codes, pagination, versioning
package com.bank.marketplace.controller;

import com.bank.marketplace.dto.*;
import com.bank.marketplace.service.FundService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/funds")   // URL-path versioning (most common)
@RequiredArgsConstructor
public class FundController {

    private final FundService fundService;

    @GetMapping("/{fundId}")
    public FundResponse getFund(@PathVariable String fundId) {
        return fundService.getFund(fundId);
    }

    // Cursor pagination: GET /api/v1/funds?size=10&after=FND-003
    @GetMapping
    public PageResponse<FundResponse> listFunds(
            @RequestParam(required = false) String after,
            @RequestParam(defaultValue = "10") int size) {
        return fundService.listFunds(after, size);
    }

    @PostMapping("/{fundId}/purchase")
    @ResponseStatus(HttpStatus.CREATED)
    public String purchase(@PathVariable String fundId,
                            @RequestBody @Valid PurchaseRequest request) {
        var fund = fundService.getFund(fundId);
        var fee = fundService.calculateFee(
            request.feeStrategy() != null ? request.feeStrategy() : "regular",
            request.amount());
        return "Purchased Rs." + request.amount() + " of " + fund.name()
            + " (fee: Rs." + fee + " via " + request.feeStrategy() + " strategy)";
    }
}
