import static org.assertj.core.api.Assertions.*;

class FundServiceTest {

    Map<String, FeeStrategy> strategies = Map.of(
        "regular", new RegularFeeStrategy(),
        "premium", new PremiumFeeStrategy(),
        "zero", new ZeroFeeStrategy());

    @Test
    void shouldCalculateRegularFee() {
        FundService service = new FundService(null, strategies);
        BigDecimal fee = service.calculateFee("regular", new BigDecimal("100000"));
        assertThat(fee).isEqualByComparingTo("1000.00");  // 1% of 100K
    }

    @Test
    void shouldCalculatePremiumFee() {
        FundService service = new FundService(null, strategies);
        BigDecimal fee = service.calculateFee("premium", new BigDecimal("100000"));
        assertThat(fee).isEqualByComparingTo("500.00");  // 0.5% of 100K
    }

    @Test
    void shouldCalculateZeroFee() {
        FundService service = new FundService(null, strategies);
        BigDecimal fee = service.calculateFee("zero", new BigDecimal("100000"));
        assertThat(fee).isEqualByComparingTo("0");
    }
}
